-- F5 job core: orders (stub), jobs, assignments, job_events (append-only), outbox, inbox.
-- Conventions: UUIDv7 ids generated by the app, money in BIGINT paise, all timestamps timestamptz (UTC).

-- Minimal order header. The full Order aggregate (invoice, payment state, frozen brief)
-- arrives with real order intake in Sprint 3-4.
CREATE TABLE orders (
    id              uuid        PRIMARY KEY,
    brand_org_id    uuid        NOT NULL,          -- Backend A org id, no FK across services
    created_at      timestamptz NOT NULL,
    version         bigint      NOT NULL
);

-- One creator x one deliverable (spec F5). Status is written only by JobTransitionService.
CREATE TABLE jobs (
    id                   uuid        PRIMARY KEY,
    order_id             uuid        NOT NULL REFERENCES orders (id),
    brand_org_id         uuid        NOT NULL,     -- copied from the order, immutable
    status               varchar(32) NOT NULL CHECK (status IN (
                             'AWAITING_PAYMENT', 'PAID', 'CREATOR_INVITED', 'CREATOR_ACCEPTED', 'DECLINED',
                             'PRODUCT_SHIPPED', 'PRODUCT_RECEIVED', 'IN_PRODUCTION', 'DRAFT_SUBMITTED',
                             'IN_REVIEW', 'REVISION_REQUESTED', 'APPROVED', 'DISPUTED', 'REPLACEMENT_NEEDED',
                             'REFUNDED', 'PAYOUT_PENDING', 'PAID_OUT', 'CLOSED', 'CANCELLED')),
    digital_only         boolean     NOT NULL,
    creator_fee_paise    bigint      NOT NULL CHECK (creator_fee_paise >= 0),
    free_revision_used   boolean     NOT NULL DEFAULT false,

    -- Deadlines (UTC). The timer worker polls these; nothing is held in memory.
    accept_due_at        timestamptz,              -- CREATOR_INVITED + 48h
    receipt_prompt_at    timestamptz,              -- PRODUCT_SHIPPED + 72h (prompt creator, alert ops)
    receipt_fallback_at  timestamptz,              -- PRODUCT_SHIPPED + 96h (auto-start production)
    production_due_at    timestamptz,              -- IN_PRODUCTION + 120h
    review_due_at        timestamptz,              -- IN_REVIEW + 120h (auto-approve)
    replacement_due_at   timestamptz,              -- REPLACEMENT_NEEDED + 10 days (refund)

    created_at           timestamptz NOT NULL,
    updated_at           timestamptz NOT NULL,
    version              bigint      NOT NULL       -- optimistic lock (@Version)
);

CREATE INDEX jobs_order_idx              ON jobs (order_id);
CREATE INDEX jobs_accept_due_idx         ON jobs (accept_due_at)       WHERE accept_due_at IS NOT NULL;
CREATE INDEX jobs_receipt_prompt_idx     ON jobs (receipt_prompt_at)   WHERE receipt_prompt_at IS NOT NULL;
CREATE INDEX jobs_receipt_fallback_idx   ON jobs (receipt_fallback_at) WHERE receipt_fallback_at IS NOT NULL;
CREATE INDEX jobs_production_due_idx     ON jobs (production_due_at)   WHERE production_due_at IS NOT NULL;
CREATE INDEX jobs_review_due_idx         ON jobs (review_due_at)       WHERE review_due_at IS NOT NULL;
CREATE INDEX jobs_replacement_due_idx    ON jobs (replacement_due_at)  WHERE replacement_due_at IS NOT NULL;

-- Which creator is on the job. A decline or replacement closes the assignment and a new one
-- opens on the same job, so payment stays attached to the job.
CREATE TABLE assignments (
    id            uuid        PRIMARY KEY,
    job_id        uuid        NOT NULL REFERENCES jobs (id),
    creator_id    uuid        NOT NULL,            -- Backend A creator id
    status        varchar(16) NOT NULL CHECK (status IN ('ACTIVE', 'CLOSED')),
    close_reason  varchar(64),
    opened_at     timestamptz NOT NULL,
    closed_at     timestamptz,
    version       bigint      NOT NULL,
    CHECK ((status = 'ACTIVE' AND closed_at IS NULL) OR (status = 'CLOSED' AND closed_at IS NOT NULL))
);

-- At most one active creator per job.
CREATE UNIQUE INDEX assignments_one_active_per_job ON assignments (job_id) WHERE status = 'ACTIVE';

-- F12-format event log, written in the same transaction as the state change.
-- Forwarded to Backend A's central log via the outbox (topic core.events.v1, Sprint 3-4).
-- No PII in payload or reason: the central log feeds LLM training.
CREATE TABLE job_events (
    event_id       uuid        PRIMARY KEY,
    event_type     varchar(64) NOT NULL,
    order_id       uuid        NOT NULL,
    job_id         uuid,                           -- null for order-level events
    job_version    bigint,                         -- job's @Version after this change: strict per-job order
    assignment_id  uuid,
    actor_type     varchar(16) NOT NULL CHECK (actor_type IN ('BRAND_ADMIN', 'BRAND_MEMBER', 'CREATOR', 'OPS', 'SYSTEM')),
    actor_id       uuid,                           -- null for SYSTEM
    action         varchar(48),
    from_state     varchar(32),
    to_state       varchar(32),
    reason         text,
    payload        jsonb       NOT NULL DEFAULT '{}'::jsonb,
    occurred_at    timestamptz NOT NULL
);

CREATE UNIQUE INDEX job_events_job_version_idx ON job_events (job_id, job_version);
CREATE INDEX job_events_order_idx ON job_events (order_id, occurred_at);

-- Append-only: reject UPDATE, DELETE and TRUNCATE at the database level.
CREATE FUNCTION job_events_reject_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'job_events is append-only: % rejected', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER job_events_no_update_delete
    BEFORE UPDATE OR DELETE ON job_events
    FOR EACH ROW EXECUTE FUNCTION job_events_reject_change();

CREATE TRIGGER job_events_no_truncate
    BEFORE TRUNCATE ON job_events
    FOR EACH STATEMENT EXECUTE FUNCTION job_events_reject_change();

-- Transactional outbox: rows are written with the business change, a relay publishes them to Kafka.
CREATE TABLE outbox (
    id            uuid         PRIMARY KEY,         -- equals the envelope eventId
    topic         varchar(128) NOT NULL,
    message_key   varchar(128) NOT NULL,
    event_type    varchar(64)  NOT NULL,
    envelope      jsonb        NOT NULL,
    created_at    timestamptz  NOT NULL,
    published_at  timestamptz,
    attempts      integer      NOT NULL DEFAULT 0,
    last_error    text
);

CREATE INDEX outbox_unpublished_idx ON outbox (created_at) WHERE published_at IS NULL;

-- Idempotent inbox: a consumer records each eventId it has handled, in the same transaction.
CREATE TABLE processed_events (
    consumer      varchar(64) NOT NULL,
    event_id      uuid        NOT NULL,
    processed_at  timestamptz NOT NULL,
    PRIMARY KEY (consumer, event_id)
);
